INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (200, '单程票未取票批量退款', 'DEFAULT', 'f2fBatchRefundQuartzTask.refundSingleTicket()', '0 0 20 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-20 11:25:10','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '甲方需求1，每天20点触发 face-pay POST /internal/f2f/batch-refund/single-ticket：扫 F2F_ORDER 的 PAID + BIZ_TYPE=01 且过静默期的单，按 DAILY_BATCH 来源逐笔退款。retCode=9998 是限流不是失败');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (205, 'TVM充值未到账批量退款', 'DEFAULT', 'f2fBatchRefundQuartzTask.refundTopup()', '0 0 20 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-20 11:25:17','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '甲方需求2，每天20点触发 face-pay POST /internal/f2f/batch-refund/topup：口径同 job 130，BIZ_TYPE=02 充值。按裁决不退 TOPUP_SUSPECT，只扫 PAID');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (210, '非现金收款批量退款', 'DEFAULT', 'f2fBatchRefundQuartzTask.refundNoCash()', '0 0 9,15,21 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-20 11:25:49','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '甲方需求3，每天9、15、21点三次触发 face-pay POST /internal/f2f/batch-refund/no-cash：口径同 job 130，BIZ_TYPE=04 非现金收款。甲方原文即一天三次，NEVER 合并成一次');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (220, '行程扣费重试', 'DEFAULT', 'gateTxnPayQuartzTask.retryDefaultChannelDebits()', '0 0 1 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-20 14:01:30','YYYY-MM-DD HH24:MI:SS'), NULL, TO_DATE('2026-09-20 15:34:41','YYYY-MM-DD HH24:MI:SS'), '甲方需求5。POST /internal/gate-txn-pay/debit/retry/default：扫 GATE_TXN_PAY 的 DEBIT_STATUS IN (RETRY,FAIL) 且 ISSUE_CHANNEL_CODE 非 07（含为空的历史行），出口是 pay-sign 与支付中心。含终态 FAIL 是业主裁决。2026-09-20 按渠道拆成 220/255 两条，两类扣费出口不同，NEVER 合回一条。三道防重扣闸 gate.debitRetry.maxTimes=5 / lookbackDays=7 / backoffMinutes=720 两条任务共用；本条专属 default.enabled 与 default.batchSize=200。详见 ADR-D149');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (255, '支付宝出行重试扣费', 'DEFAULT', 'gateTxnPayQuartzTask.retryAlipayChannelDebits()', '0 0 1 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-20 15:35:19','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '甲方需求18「支付宝出行重试扣费」。POST /internal/gate-txn-pay/debit/retry/alipay：扫 GATE_TXN_PAY 的 DEBIT_STATUS IN (RETRY,FAIL) 且 ISSUE_CHANNEL_CODE=07，走 PaySignInitiator 的支付宝分支打 alipay-pay-sign，不经过 pay-sign 与支付中心。与 220 同为1点是业主选择，两条各有独立 AtomicBoolean 与单批条数、互不阻塞。本条专属 alipay.enabled 与 alipay.batchSize=200；次数上限/回溯窗口/退避与 220 共用。2026-09-20 新增，详见 ADR-D149本条2026-09-21按用户要求任务名由「行程扣费重试(支付宝出行)」改为「支付宝出行重试扣费」，触发目标与cron未变，NEVER回退成旧名。');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (345, '补站扣费周期查询更新', 'DEFAULT', 'gateTxnPayQuartzTask.retryRecentUnpaidDebits()', '0 0/1 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-21 10:51:28','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, 'POST /internal/gate-txn-pay/debit/retry/recent：扫近10分钟内 DEBIT_STATUS IN (INIT,RETRY,FAIL) 且落库超60秒的过闸单逐笔重发扣费；不分渠道、多捞 INIT、排除离线码待重算态。业主裁决不设退避：刻意不写 DEBIT_RETRY_TIMES 与 DEBIT_NEXT_RETRY_TIME，防重扣只靠窗口上下界。与220/255并行，NEVER合并。concurrent=1，web-admin MUST 单副本。2026-09-21新增，编号先后为135、265、235、345。详见ADR-D154');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (350, '日票过期状态收敛', 'DEFAULT', 'dailyTicketQuartzTask.convergeExpiredTickets()', '0 5 * * * ?', '3', '1', '1', 'admin', TO_DATE('2026-09-22 14:52:33','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每小时第5分调 daily-ticket-server POST /internal/daily-ticket/expire/converge，把 DAILY_TICKET_INSTANCE 中有效期已过、状态还停在 ACTIVATED 或 USED 的票逐条 CAS 推进成 EXPIRED。判据两支：COUNTING_END 非空按它比，为空回退 ACTIVATE_TIME 加 PERIOD 天（激活 IF8A-32 不写 COUNTING_END，从未乘车的票该列恒空）。REFUND_LOCKED / REFUNDED 由 CAS 的 expectStatus 排除。返 9998 属限流不是失败。编号按接在当前最大号 345 之后定为 350。初始 status=1 暂停：收敛成 EXPIRED 后该票不能再退款，属行为变更，须经业主确认后置 0。');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (400, '用户主动重试扣费队列消费', 'DEFAULT', 'gateTxnPayQuartzTask.consumeRetryQueue()', '0 0/5 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-10-09 15:00:48','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, 'ADR-D169 方案 A 队列解耦。POST /internal/gate-txn-pay/retry-queue/consume：扫描 GATE_RETRY_QUEUE 表，每轮最多消费 batchSize=10 笔，调 PaySignInitiator.retryAndConverge 发起扣款。失败最多重试 maxRetries=3 次，超时 24 小时自动恢复。与 sys_job 220/255/345 并行不替代。concurrent=1，web-admin MUST 单副本。详见 ADR-D169');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (285, 'ACC参数文件同步', 'DEFAULT', 'paraQuartzTask.scanFtpPara()', '0 2/10 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-08 13:32:50','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-09-08 16:33:20','YYYY-MM-DD HH24:MI:SS'), '每10分钟扫ACC的FTP /parameter/cur/，按版本号+MD5判断有无变更，有变更则调para-server下载解析入库。禁止并发，单次调度内不循环。retCode!=0000即任务失败，明细只在para-server日志（无导入流水表）。当前正则只认0001/0004，0002/0003需人工走/para/import/directory');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (320, '黑名单加黑通知补偿', 'DEFAULT', 'blacklistChannelSyncQuartzTask.compensateAdd()', '0 0/5 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-18 18:11:27','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每5分钟触发 blacklist-server POST /internal/blacklist/channel-sync/compensate-add：扫 BLACKLIST 里 STATUS=ACTIVE 且 CHANNEL_SYNC_STATUS 为 PENDING/FAILED 的行，逐条重推支付宝渠道黑名单通知并回写三态。加黑通知的唯一兜底，服务内 afterCommit 那条快速路径是进程内非持久的、JVM 崩溃即丢。停用的后果是欠费卡在支付宝渠道仍能过闸。每轮条数由 limit 决定，不传即下游缺省 200，任务侧不循环。本轮结果看 sys_job_log 的 job_message 与服务端 scanned/success/failed');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (325, '黑名单解除通知补偿', 'DEFAULT', 'blacklistChannelSyncQuartzTask.compensateRelease()', '0 2/5 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-18 18:11:38','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每5分钟触发 blacklist-server POST /internal/blacklist/channel-sync/compensate-release：扫 BLACKLIST 里 STATUS=RELEASING 且 CHANNEL_SYNC_STATUS 为 PENDING/FAILED 的行重推解除通知，推成功才搬历史表并删主表行。比 125 更要紧：两阶段解除下通知没推成功那行仍算黑名单，停用等于运营已点解除、用户却永远过不了闸。载体在主表，BLACKLIST_RELEASED 的 CHANNEL_SYNC_* 已降级为审计、NEVER 据它扫表。与 125 错开2分钟，避免同时打同一服务');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (230, '自动解除黑名单', 'DEFAULT', 'blacklistAutoReleaseQuartzTask.autoRelease()', '0 0 10,16 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-21 10:17:33','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每天10点与16点各触发一次 blacklist-server POST /internal/blacklist/auto-release：扫 BLACKLIST 里 STATUS=ACTIVE 且 BLACK_CAUSE=01（欠费类）的行，按 CHANNEL_CODE 路由到对应欠费源（01 地铁APP 查闸机出站扣费、02 支付宝查支付宝出行、99 未知渠道跳过不处理），返回已结清才走 deleteBlackList 的两阶段解除。BLACK_CAUSE 只取 01 是安全边界：02 挂失补卡即便欠费清了也不能自动放行，09 其他无判据，这两类只能人工解除。欠费查询失败一律跳过、NEVER 当成已结清。结果看 sys_job_log 与服务端 scanned/released/unsettled/unknown/skipped/failed');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (410, 'ACC设备台账同步', 'DEFAULT', 'paraQuartzTask.syncDevice()', '0 0 3 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-11-04 15:22:21','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每日全量同步ACC设备台账到para-server TBL_DEVICE_INFO，业主管理模式字段不受同步影响');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (1, '系统默认（无参）', 'DEFAULT', 'ryTask.ryNoParams', '0/10 * * * * ?', '3', '1', '1', 'admin', TO_DATE('2026-07-21 13:26:56','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL);
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (2, '系统默认（有参）', 'DEFAULT', 'ryTask.ryParams(''ry'')', '0/15 * * * * ?', '3', '1', '1', 'admin', TO_DATE('2026-07-21 13:26:56','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL);
