INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (215, '解约申请确认', 'DEFAULT', 'terminationQuartzTask.confirmTermination(''20260923112600'', 0)', '0 0 4 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-07 11:22:46','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-09-22 16:22:49','YYYY-MM-DD HH24:MI:SS'), '每天4点扫描乘客App解约申请，满4天的调用pay-sign-server确认解约');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (260, '支付宝出行销卡', 'DEFAULT', 'alipayTerminationQuartzTask.cancelCard()', '0 30 2 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-07 14:22:58','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-09-07 14:22:58','YYYY-MM-DD HH24:MI:SS'), '每天2点扫描支付宝出行请求销卡的用户，符合条件则调alipay-pay-sign-server执行销卡');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (280, '黑名单可解除性盘点', 'DEFAULT', 'blacklistReleaseInspectQuartzTask.inspect()', '0 0 10,16 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-08 11:37:14','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '只读盘点黑名单欠费结清情况并输出日志，不删除任何记录；是否解除由人工看REASON判断');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (290, '签约展示账号同步补偿', 'DEFAULT', 'accountQuartzTask.compensatePhoneSignSync()', '0 0/5 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-11 14:04:45','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每5分钟触发 account-server POST /phoneSignSyncCompensate，重推 USER_PHONE_CHANGE_LOG 中 SIGN_SYNC_STATUS 为 PENDING/FAILED 的行；单批上限200条、重试上限10次');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (295, '离线码金额补偿', 'DEFAULT', 'gateTxnPayQuartzTask.recoverOfflineFare()', '0 0/1 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-15 10:09:25','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每1分钟触发 gate-txn-pay-server POST /internal/gate-txn-pay/offline-fare/recover；重算离线码出站金额并补扣款，本轮笔数看 sys_job_log 的 job_message');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (300, '公交换乘推送', 'DEFAULT', 'gateTxnPayQuartzTask.pushMetroTransfer()', '0 0/1 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-15 10:09:32','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每1分钟触发 gate-txn-pay-server POST /internal/gate-txn-pay/metro-transfer/push；投递 METRO_TRANSFER_PUSH_TASK，原为模块内 10 秒轮询');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (355, 'HCE黑名单文件生成上传', 'DEFAULT', 'hceBlacklistFileQuartzTask.generateAndUpload()', '0 0 2 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-11-12 09:39:23','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每天凌晨2点触发 blacklist-server POST /internal/blacklist/hce-file/generate：查 BLACKLIST 里 HCE 票种（CARD_TYPE=0442/0443）的生效行（RELEASING 仍算黑名单，与判黑同口径），分配只进不退的文件版本号，生成 PRM.0013.9700.<6位版本> 二进制全量黑名单文件并上传 ACC FTP。上传失败时文件留在服务端本地目录（缺省 /tmp/hce-blacklist），响应 message 带路径，可人工补传；下一轮新版本全量文件自然覆盖。');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (225, '给ACC上传扣费交易', 'DEFAULT', 'reconQuartzTask.runDailyBatch()', '0 0 2 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-11 19:37:36','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每日一次触发 recon-server 日终对账：建批次下发抽取并轮询推进到收口，账期取 T-2 日，产出 ITP.EXP/PAY/BUS/DETAIL 并投递 FTP。recon-server 侧无任何调度，频率仅由本任务的 cron 决定。');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (305, '退款回查补偿', 'DEFAULT', 'refundCompensateQuartzTask.compensateRefundQuery()', '0 0/10 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-15 16:52:59','YYYY-MM-DD HH24:MI:SS'), NULL, TO_DATE('2026-09-28 10:34:59','YYYY-MM-DD HH24:MI:SS'), '每10分钟触发 pay-sign-server POST /internal/payment/compensateRefundQuery：扫 PAY_REFUND_DETAIL 停在 PROCESSING 的退款单，出网调支付中心退款查询并收口，收口后重算原单退款汇总。间隔必须大于下游 staleMinutes=5 分钟，禁止单次调度内循环。停用会让退款单永久悬挂。单条结果看 REFUND_STATUS，不要看 submitted');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (310, '退款汇总跨表对账', 'DEFAULT', 'refundCompensateQuartzTask.compensateRefundSummary()', '0 15 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-15 16:53:07','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每小时第15分触发 pay-sign-server POST /internal/payment/compensateRefundSummary：不出网，只重算 PAY_TXN_DETAIL 的 REFUND_AMOUNT/REFUND_STATUS。skipped 长期非0是预期（含明细已SUCCESS但原支付订单不存在的不可自愈记录，当前6条），日志按 WARN 记录，需人工核对而非本轮失败');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (330, '日票支付结果通知补偿', 'DEFAULT', 'dailyTicketQuartzTask.compensatePayNotify()', '0 0/5 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-20 10:21:35','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每5分钟通过 RPC 调用 daily-ticket-server POST /internal/daily-ticket/pay/notify，扫描 DAILY_TICKET_PAY_NOTIFY 中 PENDING 的普通日票/旅游票支付结果通知并重试 IF8B-05。daily-ticket 仅提供内部接口，不在服务内使用 @Scheduled；并发执行关闭以避免同一批通知重复投递。');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (335, '日票ACC发售通知补偿', 'DEFAULT', 'dailyTicketQuartzTask.compensateAccActiveNotify()', '0 0/5 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-20 16:07:18','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每5分钟通过 RPC 调用 daily-ticket-server POST /internal/daily-ticket/acc/active-notify，扫描 DAILY_TICKET_INSTANCE 中未成功且投递次数小于5的日票激活发售通知并重试 ACC ticketActiveNotice。daily-ticket 仅提供内部接口，不在服务内使用 @Scheduled；并发执行关闭以避免同一批通知重复投递。');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (405, '异步导出任务调度', 'DEFAULT', 'asyncExportQuartzTask.execute()', '0 */5 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-11-02 16:30:29','YYYY-MM-DD HH24:MI:SS'), NULL, TO_DATE('2026-11-06 11:52:52','YYYY-MM-DD HH24:MI:SS'), '每天凌晨2点扫描 ASYNC_EXPORT_TASK 的 PENDING 任务，按 task_code 路由到对应服务生成 xlsx');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (270, '签约结果通知补发', 'DEFAULT', 'notifyCompensateQuartzTask.compensateSignNotify()', '0 0/10 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-07 19:05:55','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-09-07 19:05:55','YYYY-MM-DD HH24:MI:SS'), '每10分钟扫APP_PAY_SIGN_REQUEST中通知失败或PENDING滞留的签约结果，重新推送APP。禁止单次调度内循环，间隔必须大于pay-sign的PENDING滞留阈值10分钟');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (275, '解约结果通知补发', 'DEFAULT', 'notifyCompensateQuartzTask.compensateTerminationNotify()', '0 5/10 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-07 19:05:55','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-09-07 19:05:55','YYYY-MM-DD HH24:MI:SS'), '每10分钟扫APP_TERMINATION_REQUEST中通知失败或PENDING滞留的解约结果，重新推送APP。与签约补发错开5分钟避免同时压pay-sign');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (240, '卡池数据导入', 'DEFAULT', 'cardPoolQuartzTask.runMaintenance()', '0 0/5 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-09 15:00:26','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每5分钟触发card-pool-server POST /internal/card-pools/maintenance：回收超时预占+按阈值向ACC申请批次补货+推进批次(FTP下载卡号文件入库)；接口只受理，结果看服务端日志与/card-pools/summary。名称对甲方口径叫卡池数据导入，实际还含预占回收，NEVER 据名字以为只做导入');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (315, '支付宝支付通道同步补偿', 'DEFAULT', 'alipayChannelSyncQuartzTask.compensate()', '0 0/5 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-18 09:43:11','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每5分钟触发 alipay-pay-sign-server POST /internal/alipay/channelSync/compensate：扫 ALIPAY_SIGN_INFO 里 CHANNEL_SYNC_STATUS 非 SUCCESS 且未超重试上限的行，逐条重推账户域支付通道并回写三态。ADR-D132 的唯一驱动源，停用等于签约首推不可达的行永久停在非 SUCCESS。每轮条数由下游 alipay.channel-sync.batch-size 决定，任务侧不循环。本轮结果看 sys_job_log 的 job_message');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (245, '多日票批量退款(当日)', 'DEFAULT', 'dailyTicketBatchRefundQuartzTask.refundDaily()', '0 0 20 * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-20 16:23:14','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '甲方需求16，每天20点触发 POST /internal/daily-ticket/batch-refund/daily。候选：ORDER_STATUS与PAY_STATUS均PAID + 无票实例(未激活) + 过等待期3天(daily.batchRefund.waitDays)；回溯7天(daily.batchRefund.daily.lookbackDays)，单批200(daily.batchRefund.limit)。旅游票按主单整单退；独立日票候选带PARENT_ORDER_NO IS NULL，NEVER去掉。retCode=9998是限流不是失败。详见ADR-D151本条2026-09-21按用户要求由job_id 135改号为245，触发目标与cron未变，NEVER回退成135。');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (250, '多日票批量退款(月度)', 'DEFAULT', 'dailyTicketBatchRefundQuartzTask.refundMonthly()', '0 0 20 L * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-20 16:23:14','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '甲方需求17，每月最后一天20点(cron用L，NEVER改回30日否则2月整月不跑)触发 POST /internal/daily-ticket/batch-refund/monthly。口径同job135，只把回溯换成60天(daily.batchRefund.monthly.lookbackDays)兜漏网单；与135谓词重叠靠UK_DAILY_TICKET_REFUND_ORDER幂等。旅游票按主单整单退；NEVER去掉PARENT_ORDER_NO IS NULL。详见ADR-D151');
INSERT INTO SYS_JOB ("JOB_ID", "JOB_NAME", "JOB_GROUP", "INVOKE_TARGET", "CRON_EXPRESSION", "MISFIRE_POLICY", "CONCURRENT", "STATUS", "CREATE_BY", "CREATE_TIME", "UPDATE_BY", "UPDATE_TIME", "REMARK") VALUES (340, '支付宝退款回查补偿', 'DEFAULT', 'alipayRefundQueryQuartzTask.compensate()', '0 0/10 * * * ?', '3', '1', '0', 'admin', TO_DATE('2026-09-20 16:51:12','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, '每10分钟触发 alipay-pay-sign-server POST /internal/alipay/refund/compensateQuery，扫 ALIPAY_REFUND_LOG 的 PROCESSING 明细回查支付中心并按终态收口；cron 间隔 MUST 大于下游5分钟静默期；结果看 SYS_JOB_LOG');
